{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to stage-1 action selection.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseverance bonus to the stage-1 value of the action chosen on the previous trial.",
      "params": [
        {
          "name": "pi",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "if last_action is not None:\n            q_stage1_net[last_action] += pi",
      "expressible_in_slots": true
    },
    {
      "name": "transition_dependent_lr",
      "title": "Transition-Dependent Learning Rate",
      "description": "Uses different learning rates for value updates depending on whether the transition to stage 2 was common or rare.",
      "params": [
        {
          "name": "alpha_common",
          "bounds": [
            0,
            1
          ]
        },
        {
          "name": "alpha_rare",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "is_common = (action_1[trial] == state_idx)\n        current_alpha = alpha_common if is_common else alpha_rare",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage-1 model-free value using the stage-2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lambda_",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += current_alpha * lambda_ * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
